import { MakeLogicType, actions, connect, kea, listeners, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { subscriptions } from 'kea-subscriptions'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

import { dashboardsRetrieve } from 'products/dashboards/frontend/generated/api'
import type { DashboardApi } from 'products/dashboards/frontend/generated/api.schemas'

import { todayLogic } from './todayLogic'

export type TodayPrimaryDashboardPickerSource = 'edit' | 'empty'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPrimaryDashboardLogicValues {
    currentProjectId: number | string // teamLogic
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    useSampleData: boolean // todayLogic
    primaryDashboard: DashboardApi | null
    primaryDashboardId: number | null
    primaryDashboardLoading: boolean
    primaryDashboardResponse: DashboardApi | null
    primaryDashboardResponseLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPrimaryDashboardLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    loadPrimaryDashboardResponse: (dashboardId: number) => number
    loadPrimaryDashboardResponseFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPrimaryDashboardResponseSuccess: (
        primaryDashboardResponse: DashboardApi | null,
        payload?: number
    ) => {
        primaryDashboardResponse: DashboardApi | null
        payload?: number
    }
    primaryDashboardOpened: (dashboardId: number) => {
        dashboardId: number
    }
    primaryDashboardPickerOpened: (source: TodayPrimaryDashboardPickerSource) => {
        source: TodayPrimaryDashboardPickerSource
    }
    setPrimaryDashboard: (
        dashboardId: number | null,
        source: TodayPrimaryDashboardPickerSource
    ) => {
        dashboardId: number | null
        source: TodayPrimaryDashboardPickerSource
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPrimaryDashboardLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        primaryDashboardId: (currentTeam: TeamPublicType | TeamType | null, useSampleData: boolean) => number | null
        primaryDashboard: (
            primaryDashboardResponse: DashboardApi | null,
            primaryDashboardId: number | null
        ) => DashboardApi | null
        primaryDashboardLoading: (
            primaryDashboardId: number | null,
            primaryDashboardResponseLoading: boolean
        ) => boolean
    }
}

export type todayPrimaryDashboardLogicType = MakeLogicType<
    todayPrimaryDashboardLogicValues,
    todayPrimaryDashboardLogicActions,
    Record<string, any>,
    todayPrimaryDashboardLogicMeta
>

export const todayPrimaryDashboardLogic = kea<todayPrimaryDashboardLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayPrimaryDashboardLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentProjectId'], todayLogic, ['useSampleData']],
        actions: [teamLogic, ['updateCurrentTeam']],
    })),
    actions({
        primaryDashboardPickerOpened: (source: TodayPrimaryDashboardPickerSource) => ({ source }),
        setPrimaryDashboard: (dashboardId: number | null, source: TodayPrimaryDashboardPickerSource) => ({
            dashboardId,
            source,
        }),
        primaryDashboardOpened: (dashboardId: number) => ({ dashboardId }),
    }),
    loaders(({ values }) => ({
        primaryDashboardResponse: [
            null as DashboardApi | null,
            {
                loadPrimaryDashboardResponse: async (dashboardId: number, breakpoint) => {
                    let dashboard: DashboardApi | null
                    try {
                        dashboard = await dashboardsRetrieve(String(values.currentProjectId), dashboardId, {
                            omit_tile_results: true,
                        })
                    } catch {
                        // A deleted or inaccessible dashboard leaves the row out rather than raising a toast on Home
                        dashboard = null
                    }
                    breakpoint()
                    return dashboard
                },
            },
        ],
    })),
    selectors({
        primaryDashboardId: [
            (s) => [s.currentTeam, s.useSampleData],
            (currentTeam: TeamPublicType | TeamType | null, useSampleData: boolean): number | null =>
                useSampleData ? null : (currentTeam?.primary_dashboard ?? null),
        ],
        primaryDashboard: [
            (s) => [s.primaryDashboardResponse, s.primaryDashboardId],
            (primaryDashboardResponse: DashboardApi | null, primaryDashboardId: number | null): DashboardApi | null =>
                primaryDashboardResponse && primaryDashboardResponse.id === primaryDashboardId
                    ? primaryDashboardResponse
                    : null,
        ],
        primaryDashboardLoading: [
            (s) => [s.primaryDashboardId, s.primaryDashboardResponseLoading],
            (primaryDashboardId: number | null, primaryDashboardResponseLoading: boolean): boolean =>
                !!primaryDashboardId && primaryDashboardResponseLoading,
        ],
    }),
    subscriptions(({ actions }) => ({
        primaryDashboardId: (primaryDashboardId: number | null) => {
            if (primaryDashboardId) {
                actions.loadPrimaryDashboardResponse(primaryDashboardId)
            }
        },
    })),
    listeners(({ actions, values }) => ({
        primaryDashboardPickerOpened: ({ source }) => {
            posthog.capture('today primary dashboard picker opened', {
                source,
                has_primary_dashboard: !!values.currentTeam?.primary_dashboard,
            })
        },
        setPrimaryDashboard: ({ dashboardId, source }) => {
            const previous = values.currentTeam?.primary_dashboard ?? null
            if (dashboardId === previous) {
                return
            }
            actions.updateCurrentTeam({ primary_dashboard: dashboardId })
            // pinned: analytics event name, shared with the dashboard choice modal
            posthog.capture('primary dashboard changed', {
                surface: 'today home',
                source,
                cleared: dashboardId === null,
                had_primary_dashboard: previous !== null,
            })
        },
        primaryDashboardOpened: ({ dashboardId }) => {
            // pinned: analytics event name, renamed from 'today primary dashboard opened' when the preview became a row
            posthog.capture('today primary dashboard row opened', { dashboard_id: dashboardId })
        },
    })),
])
